<?php require_once __DIR__.'/includes/bootstrap.php';require_role('business');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}check_csrf();$id=filter_input(INPUT_POST,'ticket_id',FILTER_VALIDATE_INT);$a=$_POST['action']??'';$rules=['call'=>['WAITING','CALLED','CALLED','called_at'],'skip'=>['WAITING','SKIPPED','SKIPPED',null],'start'=>['CALLED','IN_SERVICE','SERVICE_STARTED','service_started_at'],'complete'=>['IN_SERVICE','COMPLETED','COMPLETED','completed_at']];if(!$id||!isset($rules[$a])){notice('Invalid action','error');header('Location: business.php');exit;}$pdo=db();try{$b=$pdo->prepare('SELECT id FROM businesses WHERE owner_user_id=?');$b->execute([$_SESSION['user_id']]);$bid=(int)$b->fetchColumn();$pdo->beginTransaction();$q=$pdo->prepare('SELECT status FROM queue_tickets WHERE id=? AND business_id=? FOR UPDATE');$q->execute([$id,$bid]);$t=$q->fetch();[$from,$to,$event,$time]=$rules[$a];if(!$t||$t['status']!==$from)throw new RuntimeException('Ticket missing or action not allowed for its current status.');$sql='UPDATE queue_tickets SET status=?'.($time?', '.$time.'=NOW()':'').' WHERE id=?';$u=$pdo->prepare($sql);$u->execute([$to,$id]);$ev=$pdo->prepare('INSERT INTO queue_events(ticket_id,actor_user_id,event_type) VALUES(?,?,?)');$ev->execute([$id,$_SESSION['user_id'],$event]);$pdo->commit();notice('Ticket updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();notice($e instanceof RuntimeException?$e->getMessage():'Queue update failed.','error');}header('Location: business.php');exit;